<section class="content product-admin complete-admin"><div class="row"><div class="col-md-12"><div class="menu_btn"><a href="<?=ADMIN?>/plagins/complete-add" class="btn btn-primary"><i class="fa fa-fw fa-plus"></i> Добавить комплект</a></div><div class="card product-list-card"><div class="card-header d-flex p-0"><h3 class="card-title p-3">Список комплектов</h3></div><div class="card-body"><div class="product-table-wrap"><table id="example" class="table product-table complete-table" width="100%"><thead><tr><th>Комплект</th><th>Цена и остаток</th><th>Состав и качество</th><th>Управление</th><th>Avito</th><th>Статус</th></tr></thead></table></div></div></div></div></div></section>

<?php
$h=static fn($value)=>htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');
$extBadge=static function(string $ext):string{$ext=strtolower(trim($ext));if($ext==='')return '<span class="badge bg-danger">нет</span>';$class=$ext==='webp'?'success':(in_array($ext,['jpg','jpeg'],true)?'primary':($ext==='png'?'info':'secondary'));return '<span class="badge bg-'.$class.'">'.htmlspecialchars($ext,ENT_QUOTES,'UTF-8').'</span>';};
$hasSimilar=in_array('plagins_complete_similar',\R::inspect(),true);$rows=[];
foreach($complete as $compl){
 $cid=(int)$compl['id'];$inventory=$completeInventoryById[$cid]??['stock'=>0,'reserve'=>0,'available'=>0,'items'=>[]];$avito=$completeAvitoById[$cid]??['total'=>0,'published'=>0,'ads'=>[]];$metrics=$completeMetricsById[$cid]??['reviews'=>0,'favorites'=>0,'sales'=>0,'certification'=>['label'=>'Сертификация: не указано','class'=>'danger']];$cat=\R::findOne('category','id = ?',[(int)$compl['category_id']]);
 $gallery=\R::getAll('SELECT img FROM plagins_complete_gallery WHERE complete_id = ?',[$cid]);$mainExt=!empty($compl['img'])&&$compl['img']!=='no_image.jpg'?strtolower(pathinfo($compl['img'],PATHINFO_EXTENSION)):'';$galleryExts=[];foreach($gallery as $image)$galleryExts[]=strtolower(pathinfo((string)$image['img'],PATHINFO_EXTENSION));$galleryExts=array_values(array_unique(array_filter($galleryExts)));$galleryBadges='<span class="badge '.($gallery?'bg-success':'bg-danger').'">'.count($gallery).' фото</span>';foreach($galleryExts as $ext)$galleryBadges.=$extBadge($ext);
 $thumb=!empty($compl['img'])?'/images/complete/mini/'.$h($compl['img']):'/images/no_image.jpg';$identity='<div class="cc-product"><div class="cc-photo"><img src="'.$thumb.'" alt=""></div><div><div class="cc-id">ID '.$cid.'</div><div class="cc-category">'.$h($cat['name']??'Без категории').'</div><div class="cc-name">'.$h($compl['name']).'</div><div class="cc-counters"><span class="badge bg-secondary"><i class="fas fa-star"></i> '.(int)$metrics['reviews'].'</span><span class="badge bg-purple"><i class="fas fa-shopping-cart"></i> '.(int)$metrics['sales'].'</span><span class="badge bg-info"><i class="fas fa-bookmark"></i> '.(int)$metrics['favorites'].'</span></div></div><div class="cc-images"><div>Основная: '.$extBadge($mainExt).'</div><div>Галерея: '.$galleryBadges.'</div></div></div>';
 $products=\R::getAll('SELECT p.id product_id,p.name,cp.price,cp.discount,cp.qty FROM plagins_complete_product cp JOIN product p ON p.id=cp.product_id WHERE cp.complete_id=? ORDER BY p.name',[$cid]);$inventoryItems=[];foreach($inventory['items'] as $item)$inventoryItems[(int)$item['product_id']]=$item;$price=0.0;$composition='';
 foreach($products as $product){$item=$inventoryItems[(int)$product['product_id']]??[];$required=max(1,(int)$product['qty']);$free=(int)($item['available']??0);$reserve=(int)($item['reserve']??0);$adjustment=(int)($item['adjustment']??0);$shortage=max(0,$required-$free);$price+=max(0,(float)$product['price']-(float)$product['discount'])*$required;$composition.='<div class="cc-item'.($shortage?' is-short':'').'"><strong>'.$h($product['name']).'</strong><span>Нужно: '.$required.' шт. · Свободно: '.$free.' шт. · Резерв: '.$reserve.' шт.'.($shortage?' · Не хватает: '.$shortage.' шт.':'').'</span>'.($adjustment?'<br><em class="cc-adjustment">Корректировка: '.($adjustment>0?'+':'').$adjustment.'</em>':'').'</div>';}
 $available=(int)$inventory['available'];$priceStock='<div class="cc-price">'.number_format($price,0,'.',' ').' ₽</div><div class="cc-stock'.($available?'':' is-empty').'"><strong>'.($available?'Доступно: '.$available.' компл.':'Нет полного комплекта').'</strong><div class="cc-stock-detail">До резерва: '.(int)$inventory['stock'].' компл.<br>В резерве: '.(int)$inventory['reserve'].' компл.</div></div>';
 $scores=[trim((string)$compl['title']),trim((string)$compl['description']),trim((string)$compl['keywords']),trim((string)$compl['content']),trim((string)$compl['img'])];$seo=count(array_filter($scores,static fn($v)=>$v!==''))*20;$seoClass=$seo===100?'success':($seo>=60?'warning':'danger');$similarCount=$hasSimilar?(int)\R::getCell('SELECT COUNT(*) FROM plagins_complete_similar WHERE complete_id = ?',[$cid]):0;$quality=$composition.'<div class="cc-quality"><div>SEO '.$seo.'%<div class="progress progress-xs"><div class="progress-bar bg-'.$seoClass.'" style="width:'.$seo.'%"></div></div></div><a href="'.ADMIN.'/plagins/complete-edit?id='.$cid.'#similar">Похожие: '.$similarCount.'</a></div>';
 $status=$compl['hide']==='show'?'Активный':($compl['hide']==='lock'?'Закрыт от индексации':'Неактивный');$cert=$metrics['certification'];$actions='<div class="cc-status pc-status">'.$status.'<br><span class="badge badge-'.$h($cert['class']).' mt-1">'.$h($cert['label']).'</span></div><div class="cc-actions pc-actions"><a href="'.ADMIN.'/plagins/complete-edit?id='.$cid.'" title="Редактировать"><i class="fas fa-pencil-alt"></i></a><a class="delete" href="'.ADMIN.'/plagins/complete-delete?id='.$cid.'" title="Удалить"><i class="fas fa-times-circle text-danger"></i></a><a target="_blank" href="/complete/'.$h($compl['alias']).'" title="Открыть на сайте"><i class="fas fa-eye"></i></a><a href="'.ADMIN.'/media/convert?section=complete&amp;id='.$cid.'&amp;back='.urlencode('/admin/plagins/complete').'" title="Конвертировать изображения"><i class="fas fa-recycle"></i></a></div>';
 if((int)$avito['total']>0){$links='';foreach($avito['ads'] as $ad){$label=(string)($ad['avito_id']?:$ad['ad_external_id']?:('№'.(int)$ad['id']));$links.='<a href="'.ADMIN.'/avito/edit?id='.(int)$ad['id'].'">Объявление '.$h($label).'</a>';}$avitoCell='<div class="cc-avito pc-col-avito"><span class="badge '.((int)$avito['published']?'badge-success':'badge-warning').'">'.((int)$avito['published']?'Опубликовано на Avito':'Связано, не опубликовано').'</span><div class="cc-avito-list">'.$links.'</div></div>';}else{$avitoCell='<div class="cc-avito pc-col-avito"><span class="badge '.($available?'badge-danger':'badge-light').'">'.($available?'<i class="fas fa-exclamation-triangle"></i> Есть остаток, нет объявления':'Объявления нет').'</span><form method="post" action="'.ADMIN.'/plagins/complete-create-avito" target="_blank" class="mt-1"><input type="hidden" name="id" value="'.$cid.'"><button class="btn btn-xs btn-outline-primary" type="submit"><i class="fas fa-magic"></i> Создать по шаблону</button></form></div>';}
 $rows[]=[$identity,$priceStock,$quality,$actions,$avitoCell,(string)$compl['hide']];
}
?>
<script>
var completeDataSet=<?=json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
$(function(){var labels=['Комплект','Цена и остаток','Состав и качество','Управление','Avito'];$('#example').DataTable({data:completeDataSet,stateSave:true,autoWidth:false,responsive:false,order:[[0,'asc']],lengthMenu:[[20,50,100,-1],[20,50,100,'Все']],columnDefs:[{targets:0,className:'pc-col-product',width:'34%'},{targets:1,className:'pc-col-stock',width:'15%'},{targets:2,className:'pc-col-quality',width:'19%',orderable:false},{targets:3,className:'pc-col-management',width:'17%',orderable:false,searchable:false},{targets:4,className:'pc-col-avito',width:'15%',orderable:false},{targets:5,visible:false,searchable:false}],dom:'<"pc-table-toolbar"l f B>rt<"pc-table-footer"i p>',buttons:[{extend:'collection',text:'<i class="fas fa-download"></i> Экспорт',className:'btn-sm',buttons:['copy','csv','excel','pdf','print']}],createdRow:function(row,data){$(row).toggleClass('cc-inactive',data[5]==='hide').toggleClass('cc-locked',data[5]==='lock');$(row).children('td').each(function(i){$(this).attr('data-label',labels[i]);});}});});
